class Data {
  Data({
      String? challengeId, 
      String? quizId, 
      List<Players>? players, 
      String? result, 
      Winner? winner, 
      Loser? loser, 
      String? createdAt, 
      String? updatedAt,}){
    _challengeId = challengeId;
    _quizId = quizId;
    _players = players;
    _result = result;
    _winner = winner;
    _loser = loser;
    _createdAt = createdAt;
    _updatedAt = updatedAt;
}

  Data.fromJson(dynamic json) {
    _challengeId = json['challenge_id'];
    _quizId = json['quiz_id'];
    if (json['players'] != null) {
      _players = [];
      json['players'].forEach((v) {
        _players?.add(Players.fromJson(v));
      });
    }
    _result = json['result'];
    _winner = json['winner'] != null ? Winner.fromJson(json['winner']) : null;
    _loser = json['loser'] != null ? Loser.fromJson(json['loser']) : null;
    _createdAt = json['created_at'];
    _updatedAt = json['updated_at'];
  }
